import { useEffect, useMemo, useState } from 'react';
import { EmergencyAlertsPanel } from './components/EmergencyAlertsPanel';
import { Header } from './components/Header';
import { IntersectionSelector } from './components/IntersectionSelector';
import { ManualControlPanel } from './components/ManualControlPanel';
import { SignalStatusPanel } from './components/SignalStatusPanel';
import { TrafficChartPanel } from './components/TrafficChartPanel';
import { TrafficStatusCard } from './components/TrafficStatusCard';
import { getIntersectionStatus, getIntersections, sendManualControl } from './services/api';
import './App.css';

function App() {
  const [intersections, setIntersections] = useState([]);
  const [selectedId, setSelectedId] = useState(null);
  const [status, setStatus] = useState(null);
  const [message, setMessage] = useState('');
  const [error, setError] = useState('');

  useEffect(() => {
    getIntersections().then((items) => {
      setIntersections(items);
      if (items.length > 0) {
        setSelectedId(items[0].id);
      }
    });
  }, []);

  useEffect(() => {
    if (!selectedId) return undefined;

    const load = async () => {
      try {
        const data = await getIntersectionStatus(selectedId);
        setStatus(data);
        setError('');
      } catch {
        setError('לא ניתן לטעון את מצב הצומת כרגע.');
      }
    };

    load();
    const interval = window.setInterval(load, 5000);
    return () => window.clearInterval(interval);
  }, [selectedId]);

  const selectedIntersection = useMemo(
    () => intersections.find((item) => item.id === selectedId) || null,
    [intersections, selectedId]
  );

  async function handleManualControl(action, enabled) {
    if (!selectedId) return;
    const result = await sendManualControl(selectedId, action, enabled);
    setMessage(result.ok ? 'הפקודה נשלחה בהצלחה' : 'שליחת הפקודה נכשלה');
  }

  return (
    <div className="app-shell">
      <Header />

      {error && <div className="error-banner">{error}</div>}

      <div className="top-row">
        <IntersectionSelector
          intersections={intersections}
          selectedId={selectedId}
          onChange={setSelectedId}
        />

        <div className="card compact">
          <h2>צומת נבחרת</h2>
          <p>{selectedIntersection ? selectedIntersection.name : 'לא נבחרה צומת'}</p>
          {message && <div className="message">{message}</div>}
        </div>
      </div>

      <TrafficStatusCard status={status} />

      <div className="dashboard-grid">
        <SignalStatusPanel status={status} />
        <EmergencyAlertsPanel status={status} />
        <TrafficChartPanel status={status} />
        <ManualControlPanel onSend={handleManualControl} />
      </div>
    </div>
  );
}

export default App;
